export type BackupEvidenceId = string;

/** Owner-chosen repository label. The charset keeps a URL, path or credential from ever being stored or echoed as one. */
export type BackupLabel = string;

export type SnapshotId = string;

export interface RequiredVersion {
  /** A scope-projected manifest name, compared lexically and refused when it is absolute, traverses, uses a backslash or is Windows-ambiguous. Never resolved, opened or joined to a root. */
  relative_name: string;
  version: Digest;
}

export type BackupTopology = "independent_target" | "same_volume" | "same_physical_device" | "unknown";

/** From volumes.list identity, never from text. Different volumes stay topology unknown until a physical device identity exists. */
export type BackupTopologyBasis = "same_volume_identity" | "different_volumes_device_unknown" | "undeclared";

export type BackupRefusal = "snapshot_missing" | "version_not_covered" | "target_not_independent" | "credentials_unavailable" | "integrity_not_checked" | "restore_not_succeeded" | "partial_restore" | "unsupported_metadata" | "stale_observation" | "invalid_observation_time";

export type BackupMetadataClass = "acl" | "alternate_streams" | "hard_links" | "timestamps" | "sparse" | "compression" | "efs";

export type RestoreDrillProof = "repository_and_snapshot_binding" | "independent_content_sha256" | "required_metadata_comparison" | "complete_manifest" | "fresh_observation";

export type RestoreDrillTarget = "new_disposable_target";

/** A restore drill as data only. Nothing creates, opens, writes or restores its target; no command executes it. */
export interface ProposedRestoreDrill {
  files: RequiredVersion[];
  target: RestoreDrillTarget;
  compare_metadata: BackupMetadataClass[];
  proofs: RestoreDrillProof[];
  executable: false;
}

/** Normalised restic receipt evidence. Snapshot, integrity and restore drill are separate observations; a green backup job is not verified recovery. */
export interface BackupEvidence {
  evidence_id: BackupEvidenceId;
  repository_label: BackupLabel;
  snapshot_id: SnapshotId;
  /** The provider's own time text, uninterpreted; never the age oracle. */
  snapshot_time: string | null;
  imported_at: Timestamp;
  snapshot_observed_at: Timestamp;
  integrity_observed_at: NullableTimestamp;
  snapshot_taken: boolean;
  integrity_checked: boolean;
  integrity_read_all_data: boolean;
  restore_drill_succeeded: boolean;
  required_versions: RequiredVersion[];
  restore_coverage: RequiredVersion[];
  topology: BackupTopology;
  topology_basis: BackupTopologyBasis;
  snapshot_age_seconds: NullableCount;
  integrity_age_seconds: NullableCount;
  max_age_seconds: Count;
  /** Every predicate holds on the supplied, scoped evidence. Caller-reported self-consistency: never native proof, permission or a source-retirement gate. */
  reported_recovery_evidence: boolean;
  refusals: BackupRefusal[];
  proposed_drill: ProposedRestoreDrill;
}

export interface BackupEvidenceList {
  evidence: BackupEvidence[];
}

/** Tauri adapter only. Rust opens the native open-file dialog and reads at most 256 KiB; the webview never supplies a path. */
export interface BackupImportRequest {
  repository_label: BackupLabel;
  snapshot_id: SnapshotId;
  source_volume_id: VolumeId | null;
  target_volume_id: VolumeId | null;
  required: RequiredVersion[];
  /** Also open the dialog a second time for a restic check --json output. */
  integrity_check: boolean;
}

export type BackupImportOutcome = "imported" | "cancelled_by_user" | "refused";

export type BackupImportRefusal = "synthetic_session" | "not_a_regular_file" | "unreadable" | "too_large" | "invalid_json" | "invalid_receipt" | "invalid_source" | "repository_limit";

export interface BackupImportResult {
  outcome: BackupImportOutcome;
  evidence: BackupEvidence | null;
  refusal: BackupImportRefusal | null;
}

export interface BackupForgetRequest {
  evidence_id: BackupEvidenceId;
}

/** Removes Loomward's own record only; never touches a backup or a file. */
export interface BackupForgetResult {
  evidence_id: BackupEvidenceId;
  forgotten_at: Timestamp;
}

/** A fixed snake_case token chosen by the service; never input, a path or an OS message. */
export type UnknownReason = string;

/** A value the bundle could not read: visible, never omitted and never zero (invariant 4). */
export interface DiagnosticUnknown {
  unknown: UnknownReason;
}

export type DiagnosticsOsFamily = "windows" | "other";

/** The filesystem family, never the volume name, label or serial. */
export type DiagnosticsFilesystem = "ntfs" | "refs" | "fat" | "fat32" | "exfat" | "other";

export type DiagnosticsIdentityMode = "verified" | "unverified";

/** Keyed only by the opaque root ID: no path, name or volume label. */
export interface DiagnosticsRoot {
  root_id: RootId;
  origin: "fixture" | "lab_generated" | "owner_granted";
  grant_state: "active" | "revoked" | "identity_changed";
  scan_state: "never_scanned" | "scanning" | "complete" | "partial" | "stale" | "failed";
  coverage: CoverageState;
  filesystem: DiagnosticsFilesystem | DiagnosticUnknown;
  identity_mode: DiagnosticsIdentityMode;
}

export interface DiagnosticsJobCount {
  kind: JobKind;
  state: JobState;
  count: Count;
}

/** An allowlist by construction (docs/42 ADR-V3-24): no path, file or folder name, volume label or serial, process name or argument, label text, collection name, receipt or message. */
export interface DiagnosticsBundle {
  format: "loomward-diagnostics/1";
  generated_at: Timestamp;
  loomward: {
    engine_version: string;
    protocol: Protocol;
    adapter: "tauri" | "http";
    dataset_class: DatasetClass;
    enumeration_strategy: EnumerationStrategy;
  };
  /** Owner decision q-16 allows host hardware in new evidence; the bundle keeps it to these. */
  host: {
    os_family: DiagnosticsOsFamily;
    os_build: Count | DiagnosticUnknown;
    logical_processors: Count | DiagnosticUnknown;
    memory_total_bytes: ByteCount | DiagnosticUnknown;
  };
  session: {
    capabilities: Capabilities;
    features: SessionInfoFeatures;
  };
  health: {
    engine_private_commit_bytes: ByteCount | DiagnosticUnknown;
    engine_cpu_ms: Count | DiagnosticUnknown;
    catalog_db_bytes: ByteCount | DiagnosticUnknown;
    catalog_wal_bytes: ByteCount | DiagnosticUnknown;
    writer_queue_depth: Count;
    writer_queue_capacity: Count;
    jobs_running: Count;
    warning_codes: HealthWarningCode[];
  } | DiagnosticUnknown;
  stores: {
    catalog_schema_version: Count | DiagnosticUnknown;
    state_schema_version: Count | DiagnosticUnknown;
    catalog_files: Count | DiagnosticUnknown;
    catalog_dirs: Count | DiagnosticUnknown;
  };
  counts: {
    roots_active: Count;
    roots_revoked: Count;
    roots_identity_changed: Count;
    roots_forgotten: Count;
    collections: Count;
    human_feedback_records: Count;
    teacher_label_records: Count;
    backup_evidence: Count;
  } | DiagnosticUnknown;
  jobs: {
    window: Count;
    by_kind_state: DiagnosticsJobCount[];
  } | DiagnosticUnknown;
  roots: DiagnosticsRoot[] | DiagnosticUnknown;
  recent_errors: ErrorCode[] | DiagnosticUnknown;
}

export interface DiagnosticsPreviewResult {
  bundle: DiagnosticsBundle;
  /** Length of the exact UTF-8 serialisation diagnostics.save writes. */
  bytes: ByteCount;
  /** SHA-256 of those bytes. */
  digest: Digest;
}

/** Tauri adapter only. The digest of the preview the owner saw; Rust opens the native save dialog and the webview never supplies a path. */
export interface DiagnosticsSaveRequest {
  digest: Digest;
}

export type DiagnosticsSaveOutcome = "saved" | "cancelled_by_user" | "refused";

export type DiagnosticsSaveRefusal = "preview_changed" | "elevated_session" | "unsupported_target" | "cloud_placeholder" | "write_failed" | "dialog_busy" | "dialog_unavailable" | "dialog_no_selection";

/** Never the chosen path: it stays in Rust. */
export interface DiagnosticsSaveResult {
  outcome: DiagnosticsSaveOutcome;
  bytes_written: NullableBytes;
  refusal: DiagnosticsSaveRefusal | null;
}

/** Low free space when free < max(capacity x low_space_free_percent, low_space_free_bytes). Fast growth when a granted root's net logical growth between the oldest and newest complete scans inside growth_window_days reaches growth_bytes. alerts.configure replaces the whole record. */
export interface AlertSettings {
  /** Off until the owner enables it; gates local OS notifications only. The in-app list is always available. */
  notifications_enabled: boolean;
  low_space_free_percent: number;
  low_space_free_bytes: ByteCount;
  growth_window_days: number;
  growth_bytes: ByteCount;
}

export type AlertKind = "low_space" | "fast_growth";

/** alert is the only active alert. unknown (capacity, free space or volume not observed), insufficient_history (fewer than two complete scans in the window) and incomplete_coverage (partial scans are not comparable) say why none was raised; none reads as zero. */
export type AlertStatus = "alert" | "ok" | "unknown" | "insufficient_history" | "incomplete_coverage";

export interface AlertItem {
  kind: AlertKind;
  status: AlertStatus;
  label: string;
  volume_id: VolumeId | null;
  root_id: RootId | null;
  /** Free bytes (low_space) or net growth (fast_growth); null is unknown. */
  measured_bytes: NullableBytes;
  threshold_bytes: NullableBytes;
  capacity_bytes: NullableBytes;
  window_start: NullableTimestamp;
  window_end: NullableTimestamp;
  coverage: CoverageState;
  note: string;
}

/** Advice only, evaluated on demand from the volume space observation and the catalogue's completed scan history; no file or process effect. */
export interface AlertReport {
  evaluated_at: Timestamp;
  settings: AlertSettings;
  defaults: AlertSettings;
  active_count: Count;
  items: AlertItem[];
  notifications_note: string;
}

/** Copy-and-verify operation (docs/47). */
export type CopyOperationId = string;

/** docs/47 section 5 operation states. */
export type CopyState = "draft" | "refused" | "approved" | "expired" | "preparing" | "copying" | "staged" | "blocked" | "needs_attention" | "publishing" | "committed" | "cancelling" | "cancelled";

/** docs/47 section 7. Codes with a P or S entry are refused before any write handle exists. */
export type CopyRefusalCode = "identity_unverified" | "cloud_placeholder" | "reparse_point" | "unsupported_attribute" | "extended_attributes" | "alternate_streams_unsupported" | "too_many_streams" | "special_file" | "source_changed" | "staging_name_taken" | "staging_in_use" | "changed_after_verification" | "source_in_use" | "access_denied" | "insufficient_space" | "destination_inside_source" | "destination_cloud_synced" | "destination_unsupported_volume" | "destination_protected" | "destination_changed" | "case_collision" | "name_unrepresentable" | "path_too_long" | "publish_in_use" | "verification_mismatch" | "grant_revoked" | "elevated" | "approval_expired" | "digest_mismatch" | "manifest_limit";

export interface CopyRefusal {
  code: CopyRefusalCode;
  /** The refused entry's catalogue node, matched by its source path and native file ID. null: an operation-wide refusal, or an entry the catalogue does not hold under that identity (never a guessed node). */
  node_id: NodeId | null;
}

/** Node IDs select what the engine observes afresh; the approval binds the digest of the observed native identities, never a node ID (invariant 5). The destination is a folder under an active grant; v1 creates exactly one new folder inside it and never writes into an existing folder (docs/47 section 1, Q3). */
export interface CopyPreviewRequest {
  sources: NodeId[];
  destination_node_id: NodeId;
}

/** Built without any effect. state is draft (approvable) or refused (deselect and preview again). The digest covers membership, destination (grant, parent identity, new folder name), bytes and identities. */
export interface CopyPreview {
  operation_id: CopyOperationId;
  state: CopyState;
  digest: Digest;
  folder_name: string;
  files: Count;
  folders: Count;
  bytes: ByteCount;
  space_needed: ByteCount;
  space_reserve: ByteCount;
  same_volume: boolean;
  explicit_acl_items: Count;
  hard_link_names: Count;
  refusals: CopyRefusal[];
  refusal_count: Count;
}

/** The digest the owner saw. approve binds a single-use approval to it; start is refused unless an unexpired approval matches the digest of a manifest rebuilt from fresh observations exactly (digest_mismatch, source_changed, approval_expired, grant_revoked). */
export interface CopyConsentRequest {
  operation_id: CopyOperationId;
  digest: Digest;
}

export interface CopyApproval {
  operation_id: CopyOperationId;
  digest: Digest;
  approved_at: Timestamp;
  expires_at: Timestamp;
}

export interface CopyOperationRequest {
  operation_id: CopyOperationId;
}

/** LW-146: the refusal or fence active when the run was cancelled: a refusal code (grant_revoked for a revoked-grant fence), emergency_stop, or cancelled when none was active. */
export type CopyStopCause = CopyRefusalCode | "emergency_stop" | "cancelled";

/** LW-146: immutable pre-removal journal counts and deterministic explanation. Native identities remain in state.db. Absent until the disposition is durable; not a receipt of removal. */
export interface CopyDisposition {
  explanation: string;
  items_total: Count;
  /** Compatibility count of earlier journal checks, not a qualification. Use receipt for current claims. */
  items_verified: Count;
  items_unverified: Count;
  /** Every distinct refusal journaled during the run, including ones it resumed past; not the stopping cause. */
  refusal_codes: CopyRefusalCode[];
  stop_cause?: CopyStopCause;
  resumable_before_cancel: boolean;
  resume_possible: boolean;
}

export type CopyReceiptLabel = "read_back" | "crash_qualified" | "power_loss_qualified" | "archive_verified";

export type CopyReceiptState = "unverified" | "read_back" | "published_unverified";

/** LW-132 / ADR R1: highest evidence-supported label. Current engine emits read_back only for a completed copy; G5 unearned, LW-134/LW-136 unavailable. published_unverified is an observation, never inferred from a publish intent. */
export interface CopyReceipt {
  state: CopyReceiptState;
  highest_label: CopyReceiptLabel | null;
  items_read_back: Count;
  archive_verified_at: Timestamp | null;
  explanation: string;
}

export interface CopyStatus {
  disposition?: CopyDisposition;
  operation_id: CopyOperationId;
  state: CopyState;
  digest: Digest;
  items_total: Count;
  /** Compatibility count of earlier journal checks, not a qualification. Use receipt for current claims. */
  items_verified: Count;
  /** docs/47 Q1 default: the name (never a path) of the staging folder Loomward left in the destination parent on cancel or abandon, for the owner to remove; null otherwise. */
  staging_folder: string | null;
  /** Names (never paths) of staging folders that were intended but never identity-journaled (a crash between intent and identity): possibly empty leftovers Loomward never adopts or removes; reported for the owner (docs/47 section 5). */
  leftover_staging_folders: string[];
  refusal: CopyRefusal | null;
  /** First 64 staging-relative manifest names observed without journaled identities; never adopted or removed. */
  unjournaled_items: string[];
  /** Total observed, including names beyond the bounded list. */
  unjournaled_item_count: Count;
  receipt?: CopyReceipt;
}

/** An Ask turn (LW-118), held in memory for this session only. */
export type AskTurnId = string;

/** Optional fields an Ask grant discloses to the model (LW-067). Name, kind, extension, coverage and match type are always part of a row. */
export type AskField = "path" | "size" | "modified" | "attributes" | "volumes";

/** local is the only class that runs; a cloud profile is refused when configured (q-5 not met). */
export type AskProviderState = "not_configured" | "local";

/** Owner-entered loopback endpoint (http on 127.0.0.1, [::1] or localhost, port required) and model. No default; nothing is discovered. */
export interface AskProfile {
  base_url: string;
  model: string;
}

/** Tauri adapter only (docs/46 section 8.1). A cloud-class profile is refused with capability_unavailable, detail.reason ask_cloud_gated. null clears the profile. */
export interface AskConfigureRequest {
  profile: AskProfile | null;
}

export type McpClient = string;

export type ClientField = "path" | "size" | "modified" | "attributes" | "volumes";

export interface ClientGrantRequest {
  client: McpClient;
  roots: RootId[];
  fields: ClientField[];
  expires_at?: Timestamp;
}

export interface ClientGrantResult {
  grant_id: string;
}

export interface ClientGrantRecord {
  grant_id: string;
  client: McpClient;
  roots: RootId[];
  fields: ClientField[];
  created_at: Timestamp;
  expires_at: Timestamp | null;
  revoked_at: Timestamp | null;
}

export interface ClientGrantList {
  grants: ClientGrantRecord[];
  available_fields: ClientField[];
}

export interface ClientRevokeRequest {
  client: McpClient;
}

export interface ClientRevokeResult {
  client: McpClient;
  revoked: boolean;
}

/** Replaces the ask:local client grant (a new epoch). Every root must be an active granted root. */
export interface AskGrantRequest {
  roots: RootId[];
  fields: AskField[];
}

export interface AskGrant {
  roots: RootId[];
  fields: AskField[];
  granted_at: Timestamp;
}

export interface AskTool {
  name: string;
  backed_by: CommandName;
  read_only: true;
}

/** Reading the status never contacts the model endpoint. */
export interface AskStatus {
  provider: AskProviderState;
  profile: AskProfile | null;
  profile_digest: Digest | null;
  principal: "ask:local";
  grant: AskGrant | null;
  tools: AskTool[];
  last_turn: AskTurnId | null;
}

export interface AskTurnRequest {
  question: string;
}

export interface AskTurnRef {
  turn_id: AskTurnId;
}

export type AskTurnState = "running" | "completed" | "failed";

export type AskFailureKind = "consent_required" | "cloud_unavailable" | "not_local" | "invalid_request" | "unreachable" | "timeout" | "http_status" | "oversize" | "invalid_reply" | "broker_failed";

export interface AskFailure {
  kind: AskFailureKind;
  message: string;
  /** False only when the turn provably sent nothing. */
  dispatched: boolean;
}

/** Resolved from the turn's handle ledger, never from the answer text. resolved false: the entry no longer reads (revoked, forgotten or gone). */
export interface AskCitation {
  handle: string;
  node_id: NodeId;
  resolved: boolean;
  name: string | null;
  root_id: RootId | null;
}

/** One tool call the model made: never its arguments. A name outside the read catalogue is refused (ok false, detail unknown tool). */
export interface AskToolUse {
  name: string;
  ok: boolean;
  rows: NullableCount;
  detail: string;
}

/** One model round's disclosure record: the exact request body by digest and length, logged before it was sent. outcome is pending, ok or an AskFailureKind. */
export interface AskRound {
  round: number;
  profile_digest: Digest;
  principal: "ask:local";
  sha256: Digest;
  bytes: Count;
  dispatched: boolean;
  outcome: string;
}

/** The answer is the model's text: plain text, never an instruction, an approval or an effect. */
export interface AskTurnRecord {
  turn_id: AskTurnId;
  state: AskTurnState;
  question: string;
  started_at: Timestamp;
  finished_at: NullableTimestamp;
  answer: string | null;
  answer_truncated: boolean;
  failure: AskFailure | null;
  /** Every ledger-backed handle the answer cites; a turn mints at most 8 x 20 handles. */
  citations: AskCitation[];
  unverified: string[];
  tool_calls: AskToolUse[];
  tool_calls_total: Count;
  rounds: AskRound[];
}

export interface ReclaimPlanRequest {
  volume_id: VolumeId;
  limit: number;
  selection?: NodeId[];
}

export interface ReclaimVolume {
  volume_id: VolumeId;
  label: string | null;
  bus_type: string | null;
  capacity_bytes: NullableBytes;
  free_bytes: NullableBytes;
  reserve_bytes: NullableBytes;
}

export interface CoveredRoot {
  root_id: RootId;
  coverage: CoverageState;
  allocated_bytes: NullableBytes;
}

export type GroupKind = "tool_owned_cleanup" | "relocate" | "archive_candidates" | "informational";

export interface Relocation {
  variable_or_setting: string;
  suggested_target_volume: string | null;
}

/** Read-only facts, never a disposability claim. owner_step is display text only; unknown reclaimable bytes carry a reason, never zero. */
export interface ReclaimCandidate {
  node_id: NodeId | null;
  name: string | null;
  class: string;
  provider: string;
  kind: string | null;
  logical_bytes: NullableBytes;
  allocated_bytes: NullableBytes;
  reclaimable_bytes: NullableBytes;
  reclaimable_reason: string | null;
  observed_at: NullableTimestamp;
  coverage: CoverageState;
  owner_step: string;
  relocation: Relocation | null;
  evidence: string[];
  uncertainty: string;
}

export interface ReclaimGroup {
  kind: GroupKind;
  candidates: ReclaimCandidate[];
}

/** LW-131 R1d. Four groups in GroupKind order. Outermost active grants only; unknown sizes remain null. No effects. */
export interface ReclaimPlan {
  volume: ReclaimVolume;
  covered_roots: CoveredRoot[];
  groups: ReclaimGroup[];
  unaccounted_bytes: NullableBytes;
  rules_version: number;
  partial: boolean;
  truncated: boolean;
  budget_hit: boolean;
  selection?: ReclaimSelection;
  relief?: ReclaimRelief;
}

export interface ReclaimObserveRequest {
  volume_id: VolumeId;
  selection?: NodeId[];
}

/** LW-131 R1g counts only. Per-candidate verdicts live in state.db and reach the owner through reclaim.plan; a candidate the job did not finish stays unknown, never zero. */
export interface ReclaimObserveProgress {
  candidates_total: Count;
  candidates_done: Count;
  names_checked: Count;
}

export type SampleRole = "before" | "after";

/** #1013. estimate_bytes is the plan's estimate as the owner saw it, kept beside a before sample; it is refused with an after sample. */
export interface ReclaimSampleRequest {
  volume_id: VolumeId;
  role: SampleRole;
  estimate_bytes?: ByteCount;
}

/** #1013. Volume metadata at one moment; anything unreadable is null, never zero. */
export interface ReliefSample {
  sampled_at: Timestamp;
  capacity_bytes: NullableBytes;
  free_bytes: NullableBytes;
  recycle_bin_bytes: NullableBytes;
  estimate_bytes: NullableBytes;
}

export type ReliefStatus = "not_checked" | "different_volume" | "unreadable" | "compared";

export type ReliefDirection = "more_free" | "less_free" | "unchanged";

/** #1013, #1031. Observed free-space change between two samples of one volume identity. status compared requires an after sample, a direction and change_bytes; any other status has null direction, change_bytes and capacity_changed, and only not_checked has no after sample. capacity_changed is null when not compared or a capacity is unreadable in either sample; true means the comparison spans a capacity change. It never attributes the change to a cleanup. */
export interface ReclaimRelief {
  before: ReliefSample;
  after: ReliefSample | null;
  status: ReliefStatus;
  direction: ReliefDirection | null;
  change_bytes: NullableBytes;
  capacity_changed: boolean | null;
}

export type ReclaimSelectionStatus = "unobserved" | "recorded" | "expired";

export interface ReclaimSelection {
  members: NodeId[];
  status: ReclaimSelectionStatus;
  observed_at: NullableTimestamp;
  reclaimable_bytes: NullableBytes;
  reason: string | null;
}

export interface DeveloperClutterRequest {
  root_id: RootId;
  limit: number;
}

export type DeveloperClutterProvider = "cargo" | "npm" | "python" | "dotnet" | "gradle";

/** A reading of the conventional directory name, never of its contents. */
export type DeveloperClutterKind = "build_output" | "dependency_install" | "environment" | "bytecode_cache" | "build_cache";

/** Regeneration cost is measured by LW-087; until then every candidate says unknown. */
export type RegenerationCost = "unknown";

/** Observed bytes are not reclaimable bytes: the directory may hold unique source or datasets, and a shared store or hard links make summed sizes differ from what a removal would free. Advice only. */
export interface DeveloperClutterCandidate {
  node_id: NodeId;
  name: string;
  anchor_node_id: NodeId;
  anchor_name: string;
  provider: DeveloperClutterProvider;
  kind: DeveloperClutterKind;
  /** Observed logical bytes under the directory; null is unknown (partial, stale or unscanned), never zero. */
  logical_bytes: NullableBytes;
  /** null when any allocation under it is unknown. */
  allocated_bytes: NullableBytes;
  coverage: CoverageState;
  regeneration_cost: RegenerationCost;
  regeneration_hint: string;
  reason: string;
  uncertainty: string;
}

export type ClutterTopic = "regeneration_cost" | "model_host_lifecycle" | "stale_worktrees";

/** A part of LW-119 that no provider supplies yet (LW-087, LW-086, LW-076): said so, never filled with a value. */
export interface ClutterNotAssessed {
  topic: ClutterTopic;
  note: string;
}

/** Developer-clutter advice (LW-119) from recorded names only. Never a delete action or a disposability claim; no file or process effect. */
export interface DeveloperClutterReport {
  root_id: RootId;
  generation: NullableGeneration;
  rules_version: number;
  /** The root is mid-scan, stale or not fully covered, or a candidate size is not fully known: projects may be missing and sizes may be lower bounds. */
  partial: boolean;
  truncated: boolean;
  /** The detector reached its work budget: candidates is then empty and says nothing about the root. */
  budget_hit: boolean;
  budget_note: string | null;
  /** Largest known logical size first, then unknown sizes. */
  candidates: DeveloperClutterCandidate[];
  not_assessed: ClutterNotAssessed[];
}

